const x = $json;
const required = ['authorized_action','identity','cart_context'];
const missing = required.filter(k => x[k] === undefined || x[k] === null);
const a = x.authorized_action || {};
const allowed = ['cart_view','cart_add','cart_remove','cart_update','cart_clear'];
const action = a.action || x.intent;
const ok = !missing.length && allowed.includes(action);
return [{json:{...x, _wf12_input_valid:ok, _wf12_missing:missing, _wf12_action:action}}];

const a=$json.authorized_action||{};
const i=$json.identity||{};
const action=a.action||$json.intent;
const permitted=['channel_linked','order_verified','high_assurance'].includes(i.identity_level);
const contractOk=a.execution_allowed===true && a.action===action;
return [{json:{...$json,_wf12_auth_ok:permitted&&contractOk,_wf12_action:action}}];

const c=$json.cart_context||{};
const a=$json.authorized_action||{};
const p=a.parameters||{};
const action=a.action||$json.intent;
const item=p.item||{};
const variant=p.variant||{};
const qty=Number(p.quantity ?? 1);
const validQty=Number.isInteger(qty)&&qty>0&&qty<=99;
const hasSku=typeof (item.sku||p.sku) === 'string' && (item.sku||p.sku).length>0;
const key=[a.idempotency_key||$json.message_id||'no-key',action,item.sku||p.sku||'',variant.id||variant.size||variant.name||'',qty].join('|');
return [{json:{...$json,_wf12_params:{...p,quantity:qty},_wf12_parameter_ok:(action==='cart_view'||action==='cart_clear'||action==='cart_remove'||action==='cart_update'||(validQty&&hasSku)),_wf12_idempotency_key:key}}];

const c=$json.cart_context||{};
const a=$json.authorized_action||{};
const action=a.action||$json.intent;
const p=$json._wf12_params||{};
const existing=c.cart||{};
const idem=c.idempotency_keys||{};
const already=Boolean(idem[$json._wf12_idempotency_key]);
let variantRequired=['cart_add','cart_update'].includes(action);
let variantOk=!variantRequired || Boolean((p.variant&&((p.variant.id)||(p.variant.size)||(p.variant.name))) || p.variant_id || p.size);
let cartOk=Boolean(c.cart_id || action==='cart_view' || action==='cart_add');
let stockOk=true;
if(action==='cart_add'||action==='cart_update'){
  const stock=(c.live_stock||{})[p.sku || (p.item||{}).sku || ''];
  if(stock!==undefined) stockOk=Number(stock)>=Number(p.quantity||1);
}
return [{json:{...$json,_wf12_checks:{already,variant_ok:variantOk,cart_ok:cartOk,stock_ok:stockOk},_wf12_business_ok:!already&&variantOk&&cartOk&&stockOk}}];

const c=$json.cart_context||{};
const a=$json.authorized_action||{};
const action=a.action||$json.intent;
const p=$json._wf12_params||{};
return [{json:{...$json,status:'ready_to_execute',service:'cart',operation:action,request:{cart_id:c.cart_id||null,sku:p.sku||(p.item||{}).sku||null,variant:p.variant||{id:p.variant_id||null,size:p.size||null},quantity:p.quantity||null},execution_allowed:true,idempotency_key:$json._wf12_idempotency_key,adapter:'COMMERCE_CART_ADAPTER'}}];

const x=$json;
const exec=x.commerce_result || x.adapter_result || null;
if(!exec) return [{json:{...x,status:'awaiting_adapter',verification_status:'not_run',note:'Connect COMMERCE_CART_ADAPTER here; no success is asserted.'}}];
const verified=exec.verified===true && exec.owner_match===true;
return [{json:{...x,status:verified?'completed':'failed',verification_status:verified?'verified':'failed',execution_allowed:verified,commerce_result:verified?exec:undefined}}];

const x=$json;
return [{json:{
  service:'cart',
  status:x.status||'failed',
  action:x.operation||x._wf12_action||null,
  execution_allowed:x.execution_allowed===true,
  verification_status:x.verification_status||'not_run',
  cart:x.commerce_result?.cart || null,
  idempotency_key:x.idempotency_key||null
}}];
